const COUNT_KEY = "stars";
const state = { stars: Number(localStorage.getItem(COUNT_KEY)) || 0 };
const countEl = document.querySelector("#count");

function update(action) {
  if (action === "plus") state.stars += 1;
  if (action === "reset") state.stars = 0;
  localStorage.setItem(COUNT_KEY, String(state.stars));
}

function render() {
  countEl.textContent = `${state.stars} stars`;
}

function init() {
  document.querySelector("#plus").addEventListener("click", () => {
    update("plus");
    render();
  });
  document.querySelector("#reset").addEventListener("click", () => {
    update("reset");
    render();
  });
  render();
}

init();

class PostCard {
  constructor({ title, summary }) {
    this.title = title;
    this.summary = summary;
  }

  render() {
    const card = document.createElement("article");
    card.className = "card";
    const h3 = document.createElement("h3");
    h3.textContent = this.title;
    const p = document.createElement("p");
    p.textContent = this.summary;
    card.append(h3, p);
    return card;
  }
}

async function init() {
  const box = document.querySelector("#posts");
  try {
    const res = await fetch("/demo-api/posts");
    if (!res.ok) throw new Error(`Status code ${res.status}`);
    const posts = await res.json();
    box.textContent = "";
    posts.forEach((post) => box.append(new PostCard(post).render()));
  } catch (err) {
    box.textContent = "The posts couldn't be loaded.";
  }
}

init();

