let cities = [];
const list = document.querySelector("#list");
const search = document.querySelector("#search");

function render(items) {
  list.innerHTML = "";
  items.forEach((city) => {
    const li = document.createElement("li");
    li.textContent = city.name;
    list.append(li);
  });
  document.querySelector("#count").textContent = `${items.length} results`;
}

async function init() {
  const res = await fetch("/demo-api/cities");
  cities = await res.json();
  render(cities);
}

// filter on the input event
search.addEventListener("input", () => {
  const text = search.value.trim().toLowerCase();
  render(cities.filter((city) => city.name.toLowerCase().includes(text)));
});

init();

