async function getLevel(n) {
  const res = await fetch(`/demo-api/levels/${n}`);
  return res.json();
}

async function loadAllLevels() {
  const levels = await Promise.all([1, 2, 3].map(getLevel));
  for (const level of levels) {
    const row = document.createElement("tr");
    for (const value of [level.level, level.stars, level.enemies]) {
      const cell = document.createElement("td");
      cell.textContent = value;
      row.append(cell);
    }
    tbody.append(row);
  }
  const total = levels.reduce((sum, level) => sum + level.stars, 0);
  document.querySelector("#total").textContent = `Total: ${total} stars`;
}

loadAllLevels();

