const BEST_KEY = "best";
const GAME_LENGTH = 100;
const canvas = document.querySelector("#game");
const ctx = canvas.getContext("2d");
const state = { score: 0, time: 0, running: false };
const screens = {
  start: document.querySelector("#start-screen"),
  game: document.querySelector("#game-screen"),
  over: document.querySelector("#over-screen"),
};

// Ready: called every frame, calls endGame() when time runs out
function update() {
  if (!state.running) return;
  state.time += 1;
  if (state.time % 10 === 0) state.score += 10; // (simplified) a star was collected
  document.querySelector("#hud").textContent = `Score: ${state.score}`;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#f7df1e";
  ctx.fillRect(135, 110, 30, 30);
  if (state.time >= GAME_LENGTH) endGame();
}

function showScreen(name) {
  for (const id in screens) {
    screens[id].hidden = id !== name;
  }
}

function startGame() {
  state.score = 0;
  state.time = 0;
  state.running = true;
  showScreen("game");
}

function endGame() {
  state.running = false;
  showScreen("over");
  document.querySelector("#final-score").textContent = `Score: ${state.score}`;
  const best = Math.max(Number(localStorage.getItem(BEST_KEY)) || 0, state.score);
  localStorage.setItem(BEST_KEY, String(best));
  document.querySelector("#best").textContent = `Best: ${best}`;
}

// the Start and Play again buttons
document.querySelector("#start-btn").addEventListener("click", startGame);
document.querySelector("#again-btn").addEventListener("click", startGame);

function loop() {
  update();
  requestAnimationFrame(loop);
}
loop();
